const CACHE_DIR = join(ROOT, '.data/osm-cache')
const CACHE_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000
const EXTRACTED_AT = new Date().toISOString()
const DATE = EXTRACTED_AT.slice(0, 10)
const REFRESH = process.argv.includes('--refresh')

