const parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@_',
  textNodeName: '#text',
  isArray: (name) => ['node', 'way', 'relation', 'nd', 'tag', 'member'].includes(name),
})

function tagsOf(element) {
  const tags = {}
  for (const tag of element.tag ?? []) {
    const key = tag['@_k']
    const value = tag['@_v']
    if (key && value !== undefined) tags[key] = String(value)
  }
  return tags
}

function cleanName(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim()
}

function slug(value) {
  return cleanName(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

function round(value, digits = 7) {
  return Number(value.toFixed(digits))
}

function haversine(a, b) {
  const radius = 6_371_000
  const lat1 = (a[0] * Math.PI) / 180
  const lat2 = (b[0] * Math.PI) / 180
  const deltaLat = lat2 - lat1
  const deltaLon = ((b[1] - a[1]) * Math.PI) / 180
  const h =
    Math.sin(deltaLat / 2) ** 2 +
    Math.cos(lat1) * Math.cos(lat2) * Math.sin(deltaLon / 2) ** 2
  return 2 * radius * Math.asin(Math.sqrt(h))
}

function pointInPolygon(point, polygon) {
  let inside = false
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const [yi, xi] = polygon[i]
    const [yj, xj] = polygon[j]
    const intersects =
      yi > point[0] !== yj > point[0] &&
      point[1] < ((xj - xi) * (point[0] - yi)) / (yj - yi) + xi
    if (intersects) inside = !inside
  }
  return inside
}

function centroid(points) {
  if (!points.length) return [0, 0]
  const sum = points.reduce((acc, point) => [acc[0] + point[0], acc[1] + point[1]], [0, 0])
  return [sum[0] / points.length, sum[1] / points.length]
}

function nearestPointOnSegment(point, a, b) {
  const ax = a[1]
  const ay = a[0]
  const bx = b[1]
  const by = b[0]
  const px = point[1]
  const py = point[0]
  const dx = bx - ax
  const dy = by - ay
  if (dx === 0 && dy === 0) return a
  const t = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)))
  return [ay + t * dy, ax + t * dx]
}

function nearestPointOnPolygon(point, polygon) {
  let best = { point: polygon[0], distance: Number.POSITIVE_INFINITY }
  for (let i = 0; i < polygon.length - 1; i += 1) {
    const candidate = nearestPointOnSegment(point, polygon[i], polygon[i + 1])
    const distance = haversine(point, candidate)
    if (distance < best.distance) best = { point: candidate, distance }
  }
  return best
}

function closeRing(points) {
  if (!points.length) return points
  const first = points[0]
  const last = points[points.length - 1]
  if (first[0] === last[0] && first[1] === last[1]) return points
  return [...points, first]
}

function parseLevel(tags) {
  if (!tags.level) return null
  const first = String(tags.level).split(';')[0]
  const value = Number.parseFloat(first)
  return Number.isFinite(value) ? Math.trunc(value) : null
}

function bboxString(bbox) {
  return bbox.join(',')
}

async function loadOsmXml(airport) {
  mkdirSync(CACHE_DIR, { recursive: true })
  const cacheFile = join(CACHE_DIR, `${airport.code.toLowerCase()}.osm`)
  if (!REFRESH && existsSync(cacheFile) && Date.now() - statSync(cacheFile).mtimeMs < CACHE_MAX_AGE_MS) {
    console.log(`${airport.code}: using cached OSM extract`)
    return readFileSync(cacheFile, 'utf8')
  }
  const url = `https://api.openstreetmap.org/api/0.6/map?bbox=${bboxString(airport.bbox)}`
  console.log(`${airport.code}: fetching OSM API bbox ${bboxString(airport.bbox)}`)
  const response = await fetch(url, {
    headers: {
      'User-Agent': 'India-Airport-Navigator/1.0 (airport dataset build)',
      Accept: 'application/xml',
    },
    signal: AbortSignal.timeout(180_000),
  })
  if (!response.ok) throw new Error(`${airport.code}: OSM API returned HTTP ${response.status}`)
  const xml = await response.text()
  if (!xml.includes('<osm')) throw new Error(`${airport.code}: OSM API returned an unexpected body`)
  writeFileSync(cacheFile, xml)
  return xml
}

function buildIndex(xml) {
  const parsed = parser.parse(xml)
  const root = parsed.osm
  const nodes = new Map()
  for (const node of root.node ?? []) {
    nodes.set(String(node['@_id']), {
      id: String(node['@_id']),
      point: [Number(node['@_lat']), Number(node['@_lon'])],
      tags: tagsOf(node),
    })
  }
  const ways = new Map()
  for (const way of root.way ?? []) {
    ways.set(String(way['@_id']), {
      id: String(way['@_id']),
      refs: (way.nd ?? []).map((nd) => String(nd['@_ref'])),
      tags: tagsOf(way),
    })
  }
  const relations = new Map()
  for (const relation of root.relation ?? []) {
    relations.set(String(relation['@_id']), {
      id: String(relation['@_id']),
      tags: tagsOf(relation),
      members: (relation.member ?? []).map((member) => ({
        type: member['@_type'],
        ref: String(member['@_ref']),
        role: member['@_role'],
      })),
    })
  }
  return { nodes, ways, relations }
}

function wayPoints(way, nodes) {
  return way.refs.map((ref) => nodes.get(ref)?.point).filter(Boolean)
}

function polygonFor(ref, index) {
  const [type, id] = ref
  if (type === 'way') {
    const way = index.ways.get(id)
    if (!way) throw new Error(`Missing OSM way ${id}`)
    return closeRing(wayPoints(way, index.nodes))
  }
  const relation = index.relations.get(id)
  if (!relation) throw new Error(`Missing OSM relation ${id}`)
  const outerWays = relation.members
    .filter((member) => member.type === 'way' && member.role === 'outer')
    .map((member) => index.ways.get(member.ref))
    .filter(Boolean)
  const candidates = outerWays.length ? outerWays : relation.members
    .filter((member) => member.type === 'way')
    .map((member) => index.ways.get(member.ref))
    .filter(Boolean)
  if (!candidates.length) throw new Error(`Relation ${id} has no ways`)
  const largest = candidates.sort(
    (a, b) => wayPoints(b, index.nodes).length - wayPoints(a, index.nodes).length,
  )[0]
  return closeRing(wayPoints(largest, index.nodes))
}

const CATEGORY_LABELS = {
  gate: 'Gate',
  checkin: 'Check-in',
  security: 'Security',
  restroom: 'Restroom',
  food: 'Food & drink',
  shop: 'Shop',
  lounge: 'Lounge',
  elevator: 'Lift',
  stairs: 'Stairs',
  escalator: 'Escalator',
  entrance: 'Entrance',
  info: 'Information',
  transport: 'Transport',
  service: 'Service',
}

function categoryFor(tags) {
  if (tags.aeroway === 'gate') return 'gate'
  if (tags.aeroway === 'checkin' || tags.amenity === 'checkin') return 'checkin'
  if (tags.security) return 'security'
  if (tags.amenity === 'toilets') return 'restroom'
  if (['cafe', 'fast_food', 'restaurant', 'food_court', 'ice_cream'].includes(tags.amenity)) return 'food'
  if (tags.shop) return 'shop'
  if (tags.amenity === 'lounge') return 'lounge'
  if (tags.highway === 'elevator' || tags.elevator === 'yes') return 'elevator'
  if (tags.highway === 'steps') return 'stairs'
  if (tags.highway === 'escalator' || tags.conveying) return 'escalator'
  if (tags.entrance || tags.door) return 'entrance'
  if (tags.tourism === 'information' || tags.information || tags.amenity === 'information') return 'info'
  if (
    tags.highway === 'bus_stop' ||
    tags.public_transport === 'platform' ||
    tags.public_transport === 'stop_position' ||
    tags.amenity === 'bus_station' ||
    tags.amenity === 'taxi' ||
    tags.railway === 'station'
  ) return 'transport'
  if (['atm', 'bank', 'bureau_de_change', 'car_rental', 'drinking_water', 'pharmacy'].includes(tags.amenity)) {
    return 'service'
  }
  return null
}

function terminalForPoint(point, terminals) {
  let best = null
  for (const terminal of terminals) {
    if (pointInPolygon(point, terminal.polygon)) return { terminal, distance: 0 }
    const nearest = nearestPointOnPolygon(point, terminal.polygon)
    if (!best || nearest.distance < best.distance) best = { terminal, distance: nearest.distance }
  }
  return best
}

function buildAirportDataset(airport, index) {
  const terminals = airport.terminals.map((definition) => {
    const polygon = polygonFor(definition.osm, index)
    if (polygon.length < 4) throw new Error(`${airport.code} ${definition.id}: empty polygon`)
    return {
      ...definition,
      polygon,
      center: centroid(polygon),
      centerPoint: { lat: round(centroid(polygon)[0]), lon: round(centroid(polygon)[1]) },
      supportedFloors: [`${definition.id}-l0`, `${definition.id}-l1`],
    }
  })

  const floorDefs = terminals.flatMap((terminal) => [
    {
      id: `${terminal.id}-l0`,
      terminalId: terminal.id,
      label: 'Arrivals, kerb & ground transport',
      shortLabel: `${terminal.name} · Ground`,
      levelIndex: 0,
      level: 0,
      mapAsset: 'osm',
      areas: [],
    },
    {
      id: `${terminal.id}-l1`,
      terminalId: terminal.id,
      label: 'Departures, security & gates',
      shortLabel: `${terminal.name} · Departures`,
      levelIndex: 1,
      level: 1,
      mapAsset: 'osm',
      areas: [],
    },
  ])

  const floorIdFor = (terminalId, level) => `${terminalId}-l${level === 0 ? 0 : 1}`

  const graphNodes = new Map()
  const edges = []
  const pois = []
  let edgeCounter = 0
  const poiKeys = new Set()
  let unconnectedPois = 0

  function addNode({ id, terminalId, floorId, point, nodeType = 'junction', osmId, name }) {
    if (graphNodes.has(id)) return graphNodes.get(id)
    const node = {
      id,
      terminalId,
      floorId,
      lat: round(point[0]),
      lon: round(point[1]),
      nodeType,
      ...(osmId ? { osmId: String(osmId) } : {}),
      ...(name ? { name } : {}),
    }
    graphNodes.set(id, node)
    return node
  }

  function addEdge(from, to, options = {}) {
    if (!from || !to || from === to) return null
    const fromNode = graphNodes.get(from)
    const toNode = graphNodes.get(to)
    if (!fromNode || !toNode) throw new Error(`Edge references missing node: ${from} -> ${to}`)
    const distance = haversine([fromNode.lat, fromNode.lon], [toNode.lat, toNode.lon])
    const transitionType = options.transitionType ?? 'walk'
    let seconds = options.estimatedWalkingSeconds
    if (seconds === undefined) {
      if (transitionType === 'elevator') seconds = 30 + distance / 1.25
      else if (transitionType === 'stairs') seconds = distance / 0.6
      else if (transitionType === 'escalator') seconds = distance / 0.8
      else if (transitionType === 'shuttle') seconds = (options.travelMinutes ?? 15) * 60 + (options.waitMinutes ?? 10) * 60
      else seconds = distance / 1.25
    }
    const edge = {
      id: `edge-${++edgeCounter}`,
      from,
      to,
      distanceMeters: round(Math.max(1, options.distanceMeters ?? distance), 1),
      estimatedWalkingSeconds: Math.max(1, Math.round(seconds)),
      transitionType,
      allowedPassengerTypes: options.allowedPassengerTypes ?? ['departing', 'connecting', 'staff'],
      accessible: options.accessible ?? true,
      verificationStatus: options.verificationStatus ?? 'inferred',
      source: options.source ?? 'derived',
      ...(options.instruction ? { instruction: options.instruction } : {}),
      ...(options.wayId ? { wayId: String(options.wayId) } : {}),
      ...(options.name ? { name: options.name } : {}),
      ...(options.geometry
        ? { geometry: options.geometry.map(([lat, lon]) => [round(lat), round(lon)]) }
        : {}),
    }
    edges.push(edge)
    return edge
  }

  function addPoi(poi) {
    const key = `${poi.name.toLowerCase()}|${poi.category}|${poi.terminalId}|${poi.floorId}`
    if (poiKeys.has(key)) return null
    poiKeys.add(key)
    pois.push(poi)
    return poi
  }

  function levelFor(tags, point, terminal) {
    const parsed = parseLevel(tags)
    if (parsed === 0 || parsed === 1) return parsed
    if (pointInPolygon(point, terminal.polygon)) return 1
    return 0
  }

  function descriptionFor(category) {
    const base = 'Mapped from OpenStreetMap. Position and opening details are not field-verified.'
    if (category === 'gate') {
      return 'Gate position mapped in OpenStreetMap. The route ends at this mapped position; confirm the gate on airport screens.'
    }
    if (category === 'entrance') return 'Mapped terminal entrance or doorway. Confirm the door with airport signage.'
    if (category === 'transport') return 'Mapped transport stop or pick-up point.'
    return `${base} Connectors to this place are inferred.`
  }

  // Gates first: they anchor each terminal's schematic graph.
  const gatesByTerminal = new Map()
  for (const node of index.nodes.values()) {
    const tags = node.tags
    const isGate =
      tags.aeroway === 'gate' ||
      (tags.aeroway === 'jet_bridge' && (tags.ref || tags.name))
    if (!isGate) continue
    const nearest = terminalForPoint(node.point, terminals)
    if (!nearest || nearest.distance > 900) continue
    const terminal = nearest.terminal
    const rawRef = cleanName(tags.ref ?? tags.name ?? '')
    if (!rawRef) continue
    const ref = rawRef.replace(/^gate\s+/i, '').replace(/^bay\s+/i, '')
    // OSM gate nodes are departure gates even when no level tag is present.
    const level = parseLevel(tags) === 0 ? 0 : 1
    const floorId = floorIdFor(terminal.id, level)
    const id = `gate-${terminal.id}-${slug(rawRef)}`
    const poi = addPoi({
      id,
      name: /^bay\s/i.test(rawRef)
        ? rawRef
        : /^(?:bus\s+)?gate\s/i.test(rawRef)
          ? rawRef
          : `Gate ${ref}`,
      category: 'gate',
      terminalId: terminal.id,
      floorId,
      lat: round(node.point[0]),
      lon: round(node.point[1]),
      nodeId: `poi:${id}`,
      source: 'osm',
      verificationStatus: 'unverified',
      description: descriptionFor('gate'),
      osmId: node.id,
    })
    if (!poi) continue
    addNode({
      id: poi.nodeId,
      terminalId: terminal.id,
      floorId,
      point: node.point,
      nodeType: 'gate',
      osmId: node.id,
      name: poi.name,
    })
    if (!gatesByTerminal.has(terminal.id)) gatesByTerminal.set(terminal.id, [])
    gatesByTerminal.get(terminal.id).push(poi)
  }

  // Named facilities inside or immediately beside each terminal.
  for (const node of index.nodes.values()) {
    const tags = node.tags
    const category = categoryFor(tags)
    if (!category || category === 'gate') continue
    if (['waste_basket', 'bench', 'camera', 'parking_position', 'shelter'].includes(tags.amenity ?? '')) continue
    const nearest = terminalForPoint(node.point, terminals)
    if (!nearest || nearest.distance > 120) continue
    const terminal = nearest.terminal
    const rawName = cleanName(tags['name:en'] ?? tags.name ?? tags.operator ?? '')
    const fallbackName = ['restroom', 'elevator', 'stairs', 'escalator', 'security', 'checkin'].includes(category)
      ? CATEGORY_LABELS[category]
      : ''
    const name = rawName || fallbackName
    if (!name) continue
    const level = levelFor(tags, node.point, terminal)
    const floorId = floorIdFor(terminal.id, level)
    const id = `osm-node-${node.id}`
    const poi = addPoi({
      id,
      name,
      category,
      terminalId: terminal.id,
      floorId,
      lat: round(node.point[0]),
      lon: round(node.point[1]),
      nodeId: `poi:${id}`,
      source: 'osm',
      verificationStatus: 'unverified',
      description: descriptionFor(category),
      osmId: node.id,
    })
    if (!poi) continue
    addNode({
      id: poi.nodeId,
      terminalId: terminal.id,
      floorId,
      point: node.point,
      nodeType: category === 'entrance' ? 'entrance' : category === 'transport' ? 'entrance' : 'facility',
      osmId: node.id,
      name: poi.name,
    })
  }

  // Named rooms/ways (some airport facilities are mapped as polygons).
  for (const way of index.ways.values()) {
    const tags = way.tags
    const category = categoryFor(tags)
    if (!category || category === 'gate') continue
    if (tags.highway || tags.aeroway === 'terminal') continue
    const points = wayPoints(way, index.nodes)
    if (points.length < 3) continue
    const center = centroid(points)
    const nearest = terminalForPoint(center, terminals)
    if (!nearest || nearest.distance > 80) continue
    const terminal = nearest.terminal
    const level = levelFor(tags, center, terminal)
    const floorId = floorIdFor(terminal.id, level)
    const rawName = cleanName(tags['name:en'] ?? tags.name ?? tags.operator ?? '')
    const fallbackName = ['restroom', 'elevator', 'stairs', 'escalator', 'security', 'checkin'].includes(category)
      ? CATEGORY_LABELS[category]
      : ''
    const name = rawName || fallbackName
    if (!name) continue
    const id = `osm-way-${way.id}`
    const poi = addPoi({
      id,
      name,
      category,
      terminalId: terminal.id,
      floorId,
      lat: round(center[0]),
      lon: round(center[1]),
      nodeId: `poi:${id}`,
      source: 'osm',
      verificationStatus: 'unverified',
      description: descriptionFor(category),
      osmId: way.id,
    })
    if (!poi) continue
    addNode({
      id: poi.nodeId,
      terminalId: terminal.id,
      floorId,
      point: center,
      nodeType: 'facility',
      osmId: way.id,
      name: poi.name,
    })
  }

  // One inferred hall/gate spine per terminal. These connectors are dashed in
  // the app and never claim to be surveyed corridors.
  const terminalHubs = new Map()
  for (const terminal of terminals) {
    const gates = (gatesByTerminal.get(terminal.id) ?? []).slice()
    gates.sort((a, b) => {
      const center = terminal.center
      const angleA = Math.atan2(a.lat - center[0], a.lon - center[1])
      const angleB = Math.atan2(b.lat - center[0], b.lon - center[1])
      return angleA - angleB
    })
    const anchorPoint = gates.length ? centroid(gates.map((poi) => [poi.lat, poi.lon])) : terminal.center
    const hubId = `anchor:${terminal.id}:hall`
    addNode({
      id: hubId,
      terminalId: terminal.id,
      floorId: `${terminal.id}-l1`,
      point: anchorPoint,
      nodeType: 'junction',
      name: `${terminal.name} hall (approx.)`,
    })
    addPoi({
      id: `anchor-poi-${terminal.id}-hall`,
      name: `${terminal.name} hall (approx.)`,
      category: 'info',
      terminalId: terminal.id,
      floorId: `${terminal.id}-l1`,
      lat: round(anchorPoint[0]),
      lon: round(anchorPoint[1]),
      nodeId: hubId,
      source: 'derived',
      verificationStatus: 'inferred',
      description:
        'Approximate central hall used as the schematic connection point for this terminal. The exact indoor position is not mapped.',
    })
    addPoi({
      id: `anchor-poi-${terminal.id}-security`,
      name: `${terminal.name} security (approx.)`,
      category: 'security',
      terminalId: terminal.id,
      floorId: `${terminal.id}-l1`,
      lat: round(anchorPoint[0]),
      lon: round(anchorPoint[1]),
      nodeId: hubId,
      source: 'derived',
      verificationStatus: 'inferred',
      description:
        'The terminal hall is used as an approximate security area because the checkpoint itself is not mapped. Follow airport signs.',
    })
    addPoi({
      id: `area-${terminal.id}-gates`,
      name: `${terminal.name} gate area`,
      category: 'gate',
      terminalId: terminal.id,
      floorId: `${terminal.id}-l1`,
      lat: round(anchorPoint[0]),
      lon: round(anchorPoint[1]),
      nodeId: hubId,
      source: 'derived',
      verificationStatus: 'inferred',
      description:
        gates.length > 0
          ? 'Approximate centroid of the mapped gates in this terminal. Use it when a live gate has no individual mapped position.'
          : 'No individual gate positions are mapped for this terminal. This is an approximate gate-area destination; confirm the exact gate on airport screens.',
    })
    terminalHubs.set(terminal.id, hubId)

    for (let indexGate = 0; indexGate < gates.length - 1; indexGate += 1) {
      addEdge(gates[indexGate].nodeId, gates[indexGate + 1].nodeId, {
        transitionType: 'walk',
        verificationStatus: 'inferred',
        source: 'derived',
        instruction: `Follow the ${terminal.name} gate connector (inferred)`,
      })
    }
    for (const gate of gates) {
      if (gate.nodeId === hubId) continue
      if (gate.floorId === floorIdFor(terminal.id, 1)) {
        addEdge(hubId, gate.nodeId, {
          transitionType: 'walk',
          verificationStatus: 'inferred',
          source: 'derived',
          instruction: `Follow the inferred ${terminal.name} hall connector to ${gate.name}`,
        })
      } else {
        addEdge(hubId, gate.nodeId, {
          transitionType: 'elevator',
          verificationStatus: 'inferred',
          source: 'derived',
          instruction: `Take the lift to ${gate.name} (inferred connector)`,
        })
      }
    }

    const entrancePoint = nearestPointOnPolygon(anchorPoint, terminal.polygon).point
    const entranceId = `anchor:${terminal.id}:entrance`
    addNode({
      id: entranceId,
      terminalId: terminal.id,
      floorId: `${terminal.id}-l0`,
      point: entrancePoint,
      nodeType: 'entrance',
      name: `${terminal.name} entrance (approx.)`,
    })
    addPoi({
      id: `anchor-poi-${terminal.id}-entrance`,
      name: `${terminal.name} entrance (approx.)`,
      category: 'entrance',
      terminalId: terminal.id,
      floorId: `${terminal.id}-l0`,
      lat: round(entrancePoint[0]),
      lon: round(entrancePoint[1]),
      nodeId: entranceId,
      source: 'derived',
      verificationStatus: 'inferred',
      description:
        'Approximate kerbside entrance derived from the terminal footprint. Confirm the door with airport signage.',
    })
    addEdge(entranceId, hubId, {
      transitionType: 'elevator',
      verificationStatus: 'inferred',
      source: 'derived',
      instruction: `Take the lift or escalator between the kerbside and the ${terminal.name} departures hall (inferred connector)`,
    })

    // Connect every remaining facility to the hall. This is a schematic
    // access connector, not a claimed corridor.
    for (const poi of pois) {
      if (poi.terminalId !== terminal.id) continue
      if (poi.nodeId === hubId) continue
      if (poi.category === 'gate') continue
      if (poi.nodeId.startsWith('anchor:')) continue
      const sameFloor = poi.floorId === `${terminal.id}-l1`
      addEdge(hubId, poi.nodeId, {
        transitionType: sameFloor ? 'walk' : 'elevator',
        verificationStatus: 'inferred',
        source: 'derived',
        instruction: sameFloor
          ? `Estimated access path to ${poi.name}`
          : `Take the lift to ${poi.name} (inferred connector)`,
      })
    }
  }

  // Airport-published inter-terminal shuttles.
  for (const transfer of airport.transfers) {
    const fromId = terminalHubs.get(transfer.from)
    const toId = terminalHubs.get(transfer.to)
    if (!fromId || !toId) continue
    const fromNode = graphNodes.get(fromId)
    const toNode = graphNodes.get(toId)
    const instruction = `Take the airport inter-terminal shuttle (about ${transfer.travelMinutes} min ride; allow about ${transfer.waitAllowanceMinutes} min for the wait). Confirm eligibility and baggage steps with staff.`
    addEdge(fromId, toId, {
      transitionType: 'shuttle',
      travelMinutes: transfer.travelMinutes,
      waitMinutes: transfer.waitAllowanceMinutes,
      distanceMeters: haversine([fromNode.lat, fromNode.lon], [toNode.lat, toNode.lon]),
      allowedPassengerTypes: ['departing', 'connecting', 'staff'],
      accessible: true,
      verificationStatus: 'unverified',
      source: 'airport',
      wayId: `inter-terminal-${transfer.from}-${transfer.to}`,
      name: 'Inter-terminal shuttle',
      instruction,
      geometry: [
        [fromNode.lat, fromNode.lon],
        [toNode.lat, toNode.lon],
      ],
    })
  }

  // Count POIs that ended up without any edge (should be none after the hall
  // connector pass, except when a terminal has no gates/facilities at all).
  const degree = new Map()
  for (const edge of edges) {
    degree.set(edge.from, (degree.get(edge.from) ?? 0) + 1)
    degree.set(edge.to, (degree.get(edge.to) ?? 0) + 1)
  }
  for (const poi of pois) {
    if ((degree.get(poi.nodeId) ?? 0) === 0) unconnectedPois += 1
  }

  // The dataset bounds are derived from the committed features rather than
  // the OSM query window. A terminal polygon can extend past a tight extract
  // bbox, and validation must still cover every committed coordinate.
  const allPoints = [
    ...terminals.flatMap((terminal) => terminal.polygon),
    ...pois.map((poi) => [poi.lat, poi.lon]),
    ...[...graphNodes.values()].map((node) => [node.lat, node.lon]),
    [airport.center.lat, airport.center.lon],
  ]
  const padding = 0.004
  const south = Math.min(...allPoints.map((point) => point[0])) - padding
  const west = Math.min(...allPoints.map((point) => point[1])) - padding
  const north = Math.max(...allPoints.map((point) => point[0])) + padding
  const east = Math.max(...allPoints.map((point) => point[1])) + padding

  const shuttleNotes = airport.shuttle.notes
  const airportMeta = {
    code: airport.code,
    name: airport.name,
    city: airport.city,
    timezone: airport.timezone,
    mapVersion: `osm-${DATE}`,
    source: 'osm',
    verificationStatus: 'unverified',
    lastUpdated: DATE,
    center: airport.center,
    bounds: {
      south: round(south),
      west: round(west),
      north: round(north),
      east: round(east),
    },
    disclaimer:
      'Terminal footprints, gates, facilities and levels are derived from OpenStreetMap and are not field-verified. Hall, entrance, security and gate connectors are inferred schematic links, not surveyed corridors. Follow airport signs and staff instructions.',
    attribution: '© OpenStreetMap contributors, ODbL 1.0',
    attributionUrl: 'https://www.openstreetmap.org/copyright',
    liveFlightSource:
      'Live provider lookup when configured; manual entry and demo flights always work. The BLR airport board is used only for BLR.',
    shuttle: {
      available: airport.shuttle.available,
      terminals: airport.terminals.map((terminal) => terminal.id),
      travelMinutes: airport.transfers[0]?.travelMinutes ?? 0,
      frequencyMinutes: airport.shuttle.frequencyMinutes ?? airport.transfers[0]?.frequencyMinutes ?? 0,
      waitAllowanceMinutes: airport.transfers[0]?.waitAllowanceMinutes ?? 0,
      stopNames: [],
      notes: shuttleNotes,
      source: airport.shuttle.source,
      retrievedAt: EXTRACTED_AT,
      geometrySource: 'Straight-line schematic connector between mapped terminal halls',
      sourceUrl: airport.shuttle.url,
    },
    terminals: terminals.map((terminal) => ({
      id: terminal.id,
      airportCode: airport.code,
      name: terminal.name,
      center: { lat: round(terminal.center[0]), lon: round(terminal.center[1]) },
      polygon: terminal.polygon.map(([lat, lon]) => [round(lat), round(lon)]),
      supportedFloors: terminal.supportedFloors,
    })),
  }

  const dataset = {
    airport: airportMeta,
    terminals: airportMeta.terminals,
    floors: floorDefs,
    pois,
    nodes: [...graphNodes.values()],
    edges,
  }

  const errors = []
  const nodeIds = new Set(graphNodes.keys())
  const floorIds = new Set(floorDefs.map((floor) => floor.id))
  for (const poi of pois) {
    if (!nodeIds.has(poi.nodeId)) errors.push(`${poi.id} has missing node`)
    if (!floorIds.has(poi.floorId)) errors.push(`${poi.id} has unknown floor`)
  }
  for (const edge of edges) {
    if (!nodeIds.has(edge.from) || !nodeIds.has(edge.to)) errors.push(`${edge.id} has missing node`)
    if (edge.from === edge.to) errors.push(`${edge.id} is a self-loop`)
    if (!(edge.distanceMeters > 0) || !(edge.estimatedWalkingSeconds > 0)) {
      errors.push(`${edge.id} has invalid cost`)
    }
  }
  if (errors.length) throw new Error(`${airport.code} dataset errors:\n- ${errors.join('\n- ')}`)

  return {
    dataset,
    meta: {
      source: 'OpenStreetMap',
      license: 'ODbL 1.0',
      licenseUrl: 'https://opendatacommons.org/licenses/odbl/1-0/',
      copyrightUrl: 'https://www.openstreetmap.org/copyright',
      extractionUrl: 'https://api.openstreetmap.org/api/0.6/map',
      extractedAt: EXTRACTED_AT,
      bbox: bboxString(airport.bbox),
      counts: {
        terminals: terminals.length,
        floors: floorDefs.length,
        pois: pois.length,
        nodes: graphNodes.size,
        edges: edges.length,
        unconnectedPois,
      },
      inferred: {
        hallConnectors: true,
        gateSpines: true,
        terminalEntrances: true,
        verticalConnectors: true,
        poiAccessConnectors: true,
        shuttleRide: airport.shuttle.available,
      },
      sources: {
        terminals: airport.terminals.map((terminal) => terminal.osm.join(':')),
        shuttle: airport.shuttle.source,
        shuttleUrl: airport.shuttle.url,
      },
      notes: [
        'OpenStreetMap is the source of terminal footprints, mapped gates and named facilities.',
        'Each terminal uses an inferred central hall, gate spine, entrance and access connectors because indoor corridors are not mapped consistently.',
        'All OSM-derived features are unverified. All derived connectors are inferred and drawn as dashed lines.',
        'Inter-terminal shuttle existence and stop directions come from the airport source; the schematic connector geometry is straight-line, not OSRM.',
      ],
    },
  }
}

for (const airport of AIRPORTS) {
  const xml = await loadOsmXml(airport)
  const index = buildIndex(xml)
  const { dataset, meta } = buildAirportDataset(airport, index)
  const folder = join(DATA_ROOT, airport.code.toLowerCase())
  mkdirSync(folder, { recursive: true })
  writeFileSync(join(folder, 'dataset.json'), `${JSON.stringify(dataset, null, 2)}\n`)
  writeFileSync(join(folder, 'meta.json'), `${JSON.stringify(meta, null, 2)}\n`)
  writeFileSync(
    join(folder, 'index.ts'),
    `import type { AirportDataset } from '@/modules/airport-directory/types'\nimport dataset from './dataset.json'\n\nexport default dataset as unknown as AirportDataset\n`,
  )
  console.log(
    `${airport.code}: ${dataset.terminals.length} terminals, ${dataset.pois.length} places, ${dataset.nodes.length} nodes, ${dataset.edges.length} edges`,
  )
}
